import{_ as e,o as t,c as r,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const p=JSON.parse('{"title":"唐·霍华德","description":"","frontmatter":{"title":"唐·霍华德","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/唐·霍华德.md","filePath":"04_people/唐·霍华德.md"}'),o={name:"04_people/唐·霍华德.md"};function i(s,a,n,h,_,d){return t(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="唐·霍华德-don-howard" tabindex="-1">唐·霍华德（Don Howard） <a class="header-anchor" href="#唐·霍华德-don-howard" aria-label="Permalink to &quot;唐·霍华德（Don Howard）&quot;">​</a></h1><ul><li><strong>角色职位</strong>：所罗门兄弟高管</li><li><strong>与巴菲特关系</strong>：所罗门兄弟危机期间的公司高管</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>唐·霍华德是所罗门兄弟公司的资深高管，在公司最动荡的时期担任管理职务。1991年，所罗门兄弟因交易员约翰·梅里韦瑟的国债投机丑闻而陷入生存危机。公司被美国财政部禁止参与国债一级市场交易，面临严重的流动性风险和声誉危机，甚至有被清盘的危险。</p><p>巴菲特在此危急关头介入投资，并亲自担任临时董事长介入危机管理。霍华德作为公司高管团队的一员，在危机应对和与监管机构的沟通中发挥了作用。在整个危机处理过程中，他与其他高管协作，配合巴菲特制定应对策略，与财政部、司法部等监管机构进行谈判。</p><p>所罗门兄弟最终通过和解协议化解了法律危机，公司得以保留营业执照并继续运营。霍华德在公司重建阶段继续任职，帮助所罗门逐步恢复正常业务秩序。这场危机深刻暴露了华尔街金融机构风控体系的重要性，也成为巴菲特评估和管理所投资公司的重要案例。霍华德作为危机亲历者，在公司的恢复与重建中留下了自己的印记。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>1991年</strong>：所罗门兄弟国债丑闻爆发，担任公司高管参与危机应对</li><li><strong>1992年</strong>：协助公司整改重组，化解与监管机构的法律纠纷</li><li><strong>1990年代中期</strong>：见证所罗门逐步整合进入伯克希尔体系</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search.html?q=唐·霍华德在2014年股东信中的原话">2014年：完整翻译|/01_letters/2014年/翻译</a></li><li><a href="/search.html?q=唐·霍华德在1992年股东信中的原话">1992年：完整翻译|/01_letters/1992年/翻译</a></li><li><a href="/search.html?q=唐·霍华德在2013年股东信中的原话">2013年：完整翻译|/01_letters/2013年/翻译</a></li><li><a href="/search.html?q=唐·霍华德在2001年股东信中的原话">2001年：完整翻译|/01_letters/2001年/翻译</a></li><li><a href="/search.html?q=唐·霍华德在1993年股东信中的原话">1993年：完整翻译|/01_letters/1993年/翻译</a></li></ul>',11)])])}const u=e(o,[["render",i]]);export{p as __pageData,u as default};
